-- Phase 3 of the NPC / bestiary work, the last creature batch: the species left
-- in two books whose other content is classes and named characters - Rifts World
-- Book 10: Juicer Uprising (the Murder-Wraith, the Juicer Techno-Zombies, the
-- Phoenix Juicer and the Vallax) and Rifts World Book 5: Triax and the NGR (the
-- Brodkil) - rows for creatures (migration 074) and their attacks in stat_attacks
-- (owner_kind 'creature').
--
-- One-off data script, run once per environment. NOT a migration.
--
-- Three rows are playable: the Murder-Wraith, a published class; the renegade
-- Techno-Zombie and the Brodkil, which the books offer as player characters. The
-- Phoenix Juicer and the Vallax are NPCs. Triax's gargoyles are not here: the
-- Conversion Book One rows are already live.
--
-- The Juicer undead are transformed humans: the books print no attribute dice for
-- the Techno-Zombies, so they roll a human's 3D6, and the Murder-Wraith rolls 3D6
-- with its printed changes (-1D4 to I.Q., M.E. and M.A., +1D4+2 to P.S.). Their pools come from
-- the living Juicer's and are described, not rolled, in pools_note.
--
-- EXTRACTED by a book-extract-worker given the NAMES of its species, every number
-- read off a 200 dpi render rather than the OCR cache. RECONCILED by
-- book-reconcile against the renders, row by row, with no disagreement. Every row
-- passes creatureFormulaGaps, the grammar the endpoint rolls with. description and
-- natural_abilities are short paraphrases - no sentence is the book's.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/add-creatures-juicer-uprising-and-triax.sql
--
-- BY CATEGORY:
--   undead (3): Murder-Wraith, Juicer Techno-Zombies, Phoenix Juicer
--   alien (1): Vallax
--   demon (1): Brodkil

INSERT INTO creatures (slug, name, category, system, playable, alignment, attributes, hp, sdc, mdc, ppe, isp, pools_note, ar, horror_factor, combat, bonuses_note, skills_note, natural_abilities, magic, psionics, size, weight, life_span, habitat, allies, enemies, occ_note, description, source_book) VALUES (
  'murder-wraith', 'Murder-Wraith', 'undead', 'rifts', 1, 'Diabolic (90%) or miscreant (10%)', '{"IQ":"3D6-1D4","ME":"3D6-1D4","MA":"3D6-1D4","PS":"3D6+1D4+2","PP":"3D6","PE":"3D6"}', NULL, NULL, NULL, 'PEx2', NULL, 'A transformed evil Juicer; the book prints no attribute dice of its own, so base is a human''s 3D6 per attribute. Note #2 changes: subtract 1D4 from I.Q., M.E. and M.A.; add 1D4+2 to P.S. (supernatural); P.E. is also made supernatural but no numeric change is printed; P.B. is ''reduced by two-thirds'' of the base roll, which the formula grammar cannot express, so P.B. is left out of attributes (see uncertain). M.D.C.: by armor only, no natural M.D.C. S.D.C./Hit Points: hit points equal the former body''s S.D.C. plus hit points combined (no formula printed; does not increase with level after transformation; destroyed at -10 hit points). Regenerates 3D6 hit points per melee round.', NULL, 14, NULL, '+2 to save vs magic and psionics, +10 to save vs horror factor (in addition to all Juicer bonuses). Invulnerable to non-magical, non-silver attacks (M.D. attacks may knock it down but not damage it). S.D.C. magic does half damage; holy/rune weapons vs vampires or undead do double (or their normal anti-vampire/undead bonus, whichever is higher). Sunlight: -1 attack and -2 to all combat bonuses while fighting in daylight; in direct sunlight, loses initiative entirely and all attacks/bonuses are halved. Must save vs insanity (+M.E. bonus) to resist its necromancer master''s orders for one melee round; the bond breaks entirely if the master dies.', 'R.C.C. Skills: as per the character''s previous life, permanently frozen at those levels.', 'Retains all prior Juicer powers; supernatural P.S. and P.E.; invulnerable to all but silver and magic; regenerates 3D6 hit points per round, destroyed only at -10; drains 1D6 P.P.E. and feeds on the flesh of a suffering victim to survive.', NULL, NULL, 'Not stated (former human body)', 'Not stated (former human body)', 'Unknown; presumed eternal, or until destroyed', 'Not stated', 'Its creator Necromancer and/or Death Cult (e.g. the Grim Reapers); zombies, skeletons, other undead, and occasionally vampires, demons, or supernatural predators', NULL, NULL, 'An evil Juicer transformed by forbidden necromantic ritual into an undying, nearly indestructible predator that tortures and feeds on living victims to sustain itself.', 'Rifts World Book 10: Juicer Uprising p.50-53');
INSERT INTO creatures (slug, name, category, system, playable, alignment, attributes, hp, sdc, mdc, ppe, isp, pools_note, ar, horror_factor, combat, bonuses_note, skills_note, natural_abilities, magic, psionics, size, weight, life_span, habitat, allies, enemies, occ_note, description, source_book) VALUES (
  'juicer-techno-zombies', 'Juicer Techno-Zombies', 'undead', 'rifts', 1, 'Irrelevant; will follow its master''s orders at any cost. Renegades who cling to their mind/personality keep the alignment they had in life.', '{"IQ":"8","ME":"N/A","MA":"N/A","PS":"3D6","PP":"3D6","PE":"3D6","PB":"3D6","Spd":"3D6"}', NULL, NULL, NULL, '0', NULL, 'Physical attributes are ''unchanged'' from the base human Juicer (no dice printed here, treated as the human 3D6 baseline); all mental attributes are ''gone'' except a fixed AI-equivalent I.Q. of 8 (M.E./M.A. have no personality left, given as N/A). Those who resist the transformation instead have all mental attributes halved (a different, non-zombie case). M.D.C.: as per body armor only, no natural M.D.C. S.D.C./hit points not restated here; nano-bots regenerate 4D6 S.D.C. or hit points per minute (4 melee rounds).', NULL, 11, NULL, 'Natural Abilities modify the base Juicer: reduce attacks per melee round by one and all combat bonuses by two points. R.C.C. skills and experience level are frozen at the moment of transformation. No magic; no psionics (any prior psionic powers are lost forever). Horror Factor 11 does not apply to renegades who retain their humanity. Renegades who retain humanity: skills keep improving with level but they can never learn new skills or gain new skill bonuses, live 2D6 years longer than normal before burning out, and progress as a normal Juicer otherwise. Roughly 400-500 Techno-Zombies serve the Vallax; about 130 additional Juicers have kept their humanity and are free of Vallax control.', 'R.C.C. Skills: frozen at the level held when transformed; a renegade who keeps his humanity continues to advance skills with level but cannot learn new ones or gain new skill bonuses.', 'A human Juicer''s body reanimated as a mindless robotic soldier for the Vallax; one fewer melee attack and -2 to combat bonuses versus the living Juicer, but nano-machines heal 4D6 S.D.C./hit points every minute.', NULL, NULL, 'Not stated (former human body)', 'Not stated (former human body)', 'The Phoenix Chip can run uninterrupted for 50 years, keeping the body operating at least that long; a renegade who keeps his humanity lives 2D6 years longer than normal, then burns out and dies.', 'Not stated', 'Vallax (masters)', NULL, NULL, 'A mind-wiped human Juicer rebuilt by alien nano-technology into an obedient bio-mechanical soldier for the Vallax, stripped of personality but not physical prowess.', 'Rifts World Book 10: Juicer Uprising p.150');
INSERT INTO creatures (slug, name, category, system, playable, alignment, attributes, hp, sdc, mdc, ppe, isp, pools_note, ar, horror_factor, combat, bonuses_note, skills_note, natural_abilities, magic, psionics, size, weight, life_span, habitat, allies, enemies, occ_note, description, source_book) VALUES (
  'phoenix-juicer', 'Phoenix Juicer', 'undead', 'rifts', 0, 'Irrelevant; will follow its master''s orders at any cost.', '{"IQ":"8","ME":"N/A","MA":"N/A","PS":"3D6","PP":"3D6","PE":"3D6","PB":"3D6","Spd":"3D6"}', NULL, NULL, NULL, '0', NULL, 'Physical attributes are ''unchanged'' (treated as the human 3D6 baseline; no dice printed here); mental attributes are ''gone'' except a fixed AI-equivalent I.Q. of 8. M.D.C.: for a Juicer who was still S.D.C.-based, take the combined former S.D.C. and hit point total, halve it, and convert the remainder to M.D.C. (no fixed formula possible, depends on the individual); a Juicer who was already an M.D.C. being is unchanged. No separate S.D.C./hit point pool remains once converted.', NULL, 14, NULL, 'Natural Abilities modify the base Juicer: reduce attacks per melee round by one and all combat bonuses by three points. Nano-bots regenerate 4D6 M.D.C. every ten minutes; all other healing powers/abilities are lost. Skills and experience level frozen at the moment the Juicer became a Techno-Zombie. No magic; no psionics (any prior powers lost forever). Only 1D4x10 Phoenix Juicers exist.', 'R.C.C. Skills: frozen at the moment the character became a zombie.', 'The rotting corpse of a Juicer whose body has died, kept moving by the Phoenix Chip and nano-machines; one fewer melee attack and -3 to combat bonuses, but heals 4D6 M.D.C. every ten minutes.', NULL, NULL, 'Not stated (former human body, now a corpse)', 'Not stated (former human body, now a corpse)', 'The Phoenix Chip and nano-machines keep the corpse functioning for 50 years after the human body has died.', 'Not stated', 'Vallax (masters)', NULL, NULL, 'An animate rotting corpse of a dead Juicer, kept mobile and combat-ready by alien nano-technology and mind control in service to the Vallax.', 'Rifts World Book 10: Juicer Uprising p.151');
INSERT INTO creatures (slug, name, category, system, playable, alignment, attributes, hp, sdc, mdc, ppe, isp, pools_note, ar, horror_factor, combat, bonuses_note, skills_note, natural_abilities, magic, psionics, size, weight, life_span, habitat, allies, enemies, occ_note, description, source_book) VALUES (
  'vallax', 'Vallax', 'alien', 'rifts', 0, 'Anarchist or evil only.', '{"IQ":"3D6+6","ME":"3D6","MA":"3D6","PS":"2D6","PP":"3D4","PE":"3D4","PB":"1D6","Spd":"3D4"}', 'PE', '3D4x10', NULL, '3D6', NULL, 'Hit Points = P.E. plus 1D6 per level of experience (per-level part omitted from the formula). S.D.C.: the carapace adds 3D4x10 on top of whatever S.D.C. is gained from physical skills (not printed). M.D.C.: none naturally; only its worn Force Field (150 M.D.C., regenerates 2D6 M.D.C./round) grants M.D.C., described separately under Vallax Weapons & Equipment, not part of this R.C.C. block. Only about 10% of Vallax have (minor) psionic abilities; no I.S.P. formula is printed.', NULL, 10, NULL, '+2 to save vs magic, +1 to save vs horror factor. Can emit a nauseating chemical ''shout'': targets without nose filters/gas masks must save vs non-lethal poison or lose initiative and have bonuses and melee attacks halved. Resistant to heat up to 150 F and cold down to -20 F without ill effect. Combat is ''as per hand to hand skills'' with no numeric skill given. Only 12 Vallax exist on Rifts Earth (8 in the underground complex, 4 elsewhere in Newtown).', 'R.C.C. Skills: select 10 skills from any category at +15%, 15 more at +10%, plus 8 secondary skills.', 'Communicates via scent and inaudible ultrasonic signals; can emit a nauseating chemical shout; tough carapace resists heat and cold extremes; vestigial limbs and forearm ''armlets'' with no stated combat use.', NULL, 'Only 10% have minor psionic abilities', 'Not stated', 'Not stated', 'Up to 1,500 years; fewer than 1 in 100 can still procreate', 'Newtown, Earth, after their ship crashed in a swamp there; otherwise unknown, from another part of the universe', 'None on Rifts Earth; relies on android and Techno-Zombie slaves', NULL, NULL, 'A secretive insectoid alien species stranded on Rifts Earth, using android infiltrators and enslaved Techno-Zombie soldiers to covertly build an invasion force.', 'Rifts World Book 10: Juicer Uprising p.153');
INSERT INTO creatures (slug, name, category, system, playable, alignment, attributes, hp, sdc, mdc, ppe, isp, pools_note, ar, horror_factor, combat, bonuses_note, skills_note, natural_abilities, magic, psionics, size, weight, life_span, habitat, allies, enemies, occ_note, description, source_book) VALUES (
  'brodkil', 'Brodkil', 'demon', 'rifts', 1, 'Selfish or Evil.', '{"IQ":"2D6+3","ME":"4D6","MA":"3D6+1","PS":"5D6+5","PP":"3D6+4","PE":"4D6","PB":"2D6","Spd":"6D6"}', NULL, NULL, '250', '2D4x10', NULL, 'The ''Player Character Attributes'' dice above are used for attributes; the book separately gives fixed ''Typical Attributes'' for an average individual: I.Q. 10, M.E. 18, M.A. 12, P.S. 30, P.P. 18, P.E. 20, P.B. 5, Spd. 22. Pure Mega-Damage Creature: Main Body 250 M.D.C.; no S.D.C. or hit point pool is given. I.S.P.: None.', NULL, 10, '{"attacks":5,"initiative":2,"strike":4,"parry":6,"dodge":6,"damage":15}', '+2 to save vs psionics, +4 to save vs magic. Because Brodkil have no supernatural, psionic, or magic powers, they can use bionic weapons/implants freely, at the cost of losing the ability to turn invisible.; damage: +15 S.D.C. (P.S. bonus)', 'Skills of Note: all usually about 4th level - hand to hand basic or expert, boxing, wrestling, climbing, tracking, intelligence, radio: basic, pilot hover craft, three languages, W.P. knife, sword, blunt, and energy rifle. G.M.s may add skills from weapon proficiencies, communications, technical, domestic, and wilderness categories (no bonuses).', 'Mega-damage body immune to normal fire and cold; prowls at 40%; turns invisible at will; regenerates 2D6 M.D.C. per hour; commonly carries partial bionic augmentation without losing power, aside from invisibility.', NULL, NULL, 'Approximately 9 feet (2.7 m)', '350 lbs (103 kg)', 'Not stated', 'Nomadic wilderness raiders; large hidden concentrations in the Czech and Carpathian mountains of Europe', 'The Gargoyle Empire (a lasting alliance); lesser demons, simvan, and other monstrous D-Bees who join their armies', 'The New German Republic; the human and D-Bee populations of Poland and surrounding lands', NULL, 'Superhuman, invisibility-capable raiding giants with mega-damage bodies and a fondness for bionics, who plunder Europe''s wilderness and now quietly build an empire.', 'Rifts World Book 5: Triax and the NGR p.220-221');

INSERT INTO stat_attacks (owner_kind, owner_slug, name, damage, is_mega_damage, range, note, sort) VALUES
  ('creature', 'vallax', 'Bite', '2D4', 0, 'melee', 'S.D.C. damage', 0),
  ('creature', 'vallax', 'Claw Strike', '1D6', 0, 'melee', 'S.D.C. damage', 1),
  ('creature', 'brodkil', 'Restrained Punch', '4D6+15 (P.S.)', 0, 'melee', 'S.D.C. damage', 0),
  ('creature', 'brodkil', 'Full Strength Punch', '2D6', 1, 'melee', '', 1),
  ('creature', 'brodkil', 'Power Punch', '4D6', 1, 'melee', 'counts as two melee attacks', 2),
  ('creature', 'brodkil', 'Bionic Arm Power Punch', '3D6', 1, 'melee', 'requires a bionic arm', 3),
  ('creature', 'brodkil', 'Tear', '2D6', 1, 'melee', '', 4),
  ('creature', 'brodkil', 'Crush', '1D6', 1, 'melee', '', 5),
  ('creature', 'brodkil', 'Bite', '1D4', 1, 'melee', '', 6),
  ('creature', 'brodkil', 'Body Flip/Throw', '6D6+15 (P.S.)', 0, 'melee', 'S.D.C. damage', 7);

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 5 creatures are in' AS assertion, count(*) AS got, 5 AS want
  FROM creatures WHERE slug IN ('murder-wraith', 'juicer-techno-zombies', 'phoenix-juicer', 'vallax', 'brodkil');
SELECT 'and their 10 attacks' AS assertion, count(*) AS got, 10 AS want
  FROM stat_attacks WHERE owner_kind = 'creature' AND owner_slug IN ('murder-wraith', 'juicer-techno-zombies', 'phoenix-juicer', 'vallax', 'brodkil');

